INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7615722, 1232917, 24454, '<td valign="top">I''m not voting in this challenge because I don''t vote on challenges I have entered, but I have to tell you, this is one of the most beautiful winter images I have ever seen.  If this doesn''t win, it will truly be a shame!</td>', 'I''m not voting in this challenge because I don''t vote on challenges I have entered, but I have to tell you, this is one of the most beautiful winter images I have ever seen.  If this doesn''t win, it will truly be a shame!', '2019-02-27 00:13:27.000000', NULL, 1),
(7615729, 1232917, 114285, '<td valign="top">Gorgeous light on the rock. Would of loved this in landscape mode. Fits challenge well though.</td>', 'Gorgeous light on the rock. Would of loved this in landscape mode. Fits challenge well though.', '2019-02-27 01:46:45.000000', NULL, 1),
(7615730, 1232908, 114285, '<td valign="top">Fits challenge, but there is too much to look at, not really a good focal point... keep it simple next time.</td>', 'Fits challenge, but there is too much to look at, not really a good focal point... keep it simple next time.', '2019-02-27 01:47:44.000000', NULL, 1),
(7615740, 1233291, 114285, '<td valign="top">Hmm, I wonder whose this is :)<br/> <br/>Very nice~</td>', 'Hmm, I wonder whose this is :) Very nice~', '2019-02-27 03:14:17.000000', NULL, 1),
(7615741, 1233033, 114285, '<td valign="top">Love the birds and the pink hues, but his is slightly out of focus, and lacks a bit of oomph.</td>', 'Love the birds and the pink hues, but his is slightly out of focus, and lacks a bit of oomph.', '2019-02-27 03:16:19.000000', NULL, 1),
(7615742, 1233096, 114285, '<td valign="top">Mnet classic :)</td>', 'Mnet classic :)', '2019-02-27 03:17:08.000000', NULL, 1),
(7615792, 1233173, 179769, '<td valign="top">A climber in a red coat would make this just about perfect.  :-)</td>', 'A climber in a red coat would make this just about perfect.  :-)', '2019-02-27 12:06:06.000000', NULL, 1),
(7615946, 1233291, 46601, '<td valign="top">7 - Great shot, would have voted a little higher if it wasn''t so centered.</td>', '7 - Great shot, would have voted a little higher if it wasn''t so centered.', '2019-02-28 00:23:40.000000', NULL, 1),
(7615949, 1233294, 24983, '<td valign="top">Oh I just love this 9</td>', 'Oh I just love this 9', '2019-02-28 03:29:48.000000', NULL, 1),
(7615957, 1232536, 114285, '<td valign="top">Very pretty scene.</td>', 'Very pretty scene.', '2019-02-28 03:54:28.000000', NULL, 1),
(7616049, 1233203, 66267, '<td valign="top">i think a black and white treatment would''ve been more effective here</td>', 'i think a black and white treatment would''ve been more effective here', '2019-02-28 17:10:57.000000', NULL, 1),
(7616204, 1232536, 42733, '<td valign="top">Perfect for the theme of the challenge. Could be a Christmas card.</td>', 'Perfect for the theme of the challenge. Could be a Christmas card.', '2019-03-01 06:32:21.000000', NULL, 1),
(7616205, 1233096, 42733, '<td valign="top">My pick for yellow in this challenge.</td>', 'My pick for yellow in this challenge.', '2019-03-01 06:37:15.000000', NULL, 1),
(7616206, 1232793, 42733, '<td valign="top">My pick for red in this challenge. The use of people in a landscape I often find distracting, but here it seems to work for scale -- the mountain is more exciting because of the size contrast.</td>', 'My pick for red in this challenge. The use of people in a landscape I often find distracting, but here it seems to work for scale -- the mountain is more exciting because of the size contrast.', '2019-03-01 06:38:48.000000', NULL, 1),
(7616207, 1232917, 42733, '<td valign="top">My favorite in this challenge. What wonderful light!</td>', 'My favorite in this challenge. What wonderful light!', '2019-03-01 06:39:40.000000', NULL, 1),
(7616248, 1232563, 30669, '<td valign="top">I would have liked this if it was sharper.</td>', 'I would have liked this if it was sharper.', '2019-03-01 10:32:55.000000', NULL, 1),
(7616249, 1233264, 30669, '<td valign="top">I would have liked this better if it was sharper. Good composition.</td>', 'I would have liked this better if it was sharper. Good composition.', '2019-03-01 10:34:13.000000', NULL, 1),
(7616255, 1233301, 124815, '<td valign="top">Beautiful and scary</td>', 'Beautiful and scary', '2019-03-01 10:48:08.000000', NULL, 1),
(7616256, 1232635, 124815, '<td valign="top">Love the foreground and all</td>', 'Love the foreground and all', '2019-03-01 10:49:03.000000', NULL, 1),
(7616258, 1233096, 124815, '<td valign="top">The secrets of the mountain are glimpsed here</td>', 'The secrets of the mountain are glimpsed here', '2019-03-01 10:49:56.000000', NULL, 1),
(7616259, 1233308, 124815, '<td valign="top">Leaving with dainty dance steps...</td>', 'Leaving with dainty dance steps...', '2019-03-01 10:51:00.000000', NULL, 1),
(7616260, 1232985, 124815, '<td valign="top">Painterly in the best sense of the word<br/>a favorite</td>', 'Painterly in the best sense of the worda favorite', '2019-03-01 10:52:24.000000', NULL, 1),
(7616261, 1232803, 124815, '<td valign="top">My first thought was :Tibet!<br/>I love the feeling of enormous horizontality and its silence. The spatial relation.  Splendid work</td>', 'My first thought was :Tibet!I love the feeling of enormous horizontality and its silence. The spatial relation.  Splendid work', '2019-03-01 10:56:52.000000', NULL, 1),
(7616262, 1233240, 124815, '<td valign="top">Beautiful coloration and processing</td>', 'Beautiful coloration and processing', '2019-03-01 10:57:50.000000', NULL, 1),
(7616263, 1232823, 124815, '<td valign="top">beautiful snow falling</td>', 'beautiful snow falling', '2019-03-01 11:00:12.000000', NULL, 1),
(7616264, 1232629, 124815, '<td valign="top">Great movement</td>', 'Great movement', '2019-03-01 11:00:45.000000', NULL, 1),
(7616554, 1233096, 3306, '<td valign="top">Very nice image. I can feel the wind blow and the cold air. One of the top 2 pictures in this challenge as far as I am concerned. The other one is not mine!</td>', 'Very nice image. I can feel the wind blow and the cold air. One of the top 2 pictures in this challenge as far as I am concerned. The other one is not mine!', '2019-03-02 19:19:01.000000', NULL, 1),
(7616555, 1232917, 3306, '<td valign="top">A masterful exposure. The sun on the rocks and the reflection in the water emphasized by the deep depth of focus brings into harmony the entire scene. Top 2.<br/><br/><i>Message edited by author 2019-08-11 20:28:46.</i></td>', 'A masterful exposure. The sun on the rocks and the reflection in the water emphasized by the deep depth of focus brings into harmony the entire scene. Top 2.', '2019-03-02 19:21:42.000000', '2019-08-11 21:28:46.000000', 1),
(7616557, 1232635, 3306, '<td valign="top">Looking up gives this image the credibility of the enormity of the mountain. The falls and the touch of sunlight add that touch of uniqueness to the scene.</td>', 'Looking up gives this image the credibility of the enormity of the mountain. The falls and the touch of sunlight add that touch of uniqueness to the scene.', '2019-03-02 19:24:05.000000', NULL, 1),
(7616709, 1233294, 59740, '<td valign="top">Nice photo. I would like to have seen a little of the person''s face.</td>', 'Nice photo. I would like to have seen a little of the person''s face.', '2019-03-03 12:06:02.000000', NULL, 1),
(7616710, 1232629, 59740, '<td valign="top">Nice shapes. I would like it better if the foreground was in focus.</td>', 'Nice shapes. I would like it better if the foreground was in focus.', '2019-03-03 12:08:09.000000', NULL, 1),
(7616712, 1232908, 59740, '<td valign="top">Looks like horizon is tilted. Also could have benefited from a more interesting sky.</td>', 'Looks like horizon is tilted. Also could have benefited from a more interesting sky.', '2019-03-03 12:09:11.000000', NULL, 1),
(7616713, 1232604, 59740, '<td valign="top">Certainly gives the feeling of winter but for me there are too many confusing elements. I can''t quite tell what the large dark structure with scalloped edges is? I guess it is a fence or wall.</td>', 'Certainly gives the feeling of winter but for me there are too many confusing elements. I can''t quite tell what the large dark structure with scalloped edges is? I guess it is a fence or wall.', '2019-03-03 12:12:00.000000', NULL, 1),
(7616716, 1233293, 59740, '<td valign="top">I like this but there are two pictures vying for may attention. My eye wanders back and forth between the fence/tree on the left and the fence/birdhouse on the right. I think the more interesting photo would be to eliminate the tree and make a vertical composition. Nice exposure and certainly feels like winter.</td>', 'I like this but there are two pictures vying for may attention. My eye wanders back and forth between the fence/tree on the left and the fence/birdhouse on the right. I think the more interesting photo would be to eliminate the tree and make a vertical composition. Nice exposure and certainly feels like winter.', '2019-03-03 12:15:34.000000', NULL, 1),
(7616717, 1233320, 59740, '<td valign="top">Certainly feels like winter but for me there is not enough of interest in the foreground.</td>', 'Certainly feels like winter but for me there is not enough of interest in the foreground.', '2019-03-03 12:16:34.000000', NULL, 1),
(7616719, 1233244, 59740, '<td valign="top">Nice try but too much out of focus and too busy. It also doesn''t feel like winter to me.</td>', 'Nice try but too much out of focus and too busy. It also doesn''t feel like winter to me.', '2019-03-03 12:18:25.000000', NULL, 1),
(7616720, 1233279, 59740, '<td valign="top">I understand the attraction of the mountains and water reflections but there is too much uninteresting sky and water. Try cropping out most of the sky and you will have a more compelling composition.</td>', 'I understand the attraction of the mountains and water reflections but there is too much uninteresting sky and water. Try cropping out most of the sky and you will have a more compelling composition.', '2019-03-03 12:20:38.000000', NULL, 1),
(7616722, 1233188, 59740, '<td valign="top">This certainly captures the feel of winter but could benefit from a sharper foreground and straightening of the horizon.<br/>Try cropping out the right part of the picture to the right of the large trees and you will have a nice vertical composition.</td>', 'This certainly captures the feel of winter but could benefit from a sharper foreground and straightening of the horizon.Try cropping out the right part of the picture to the right of the large trees and you will have a nice vertical composition.', '2019-03-03 12:22:59.000000', NULL, 1),
(7616724, 1233308, 59740, '<td valign="top">I love it. This minimalist image truly captures the feel of winter. It is one of those shots that I wish I had taken.</td>', 'I love it. This minimalist image truly captures the feel of winter. It is one of those shots that I wish I had taken.', '2019-03-03 12:24:27.000000', NULL, 1),
(7616725, 1232697, 59740, '<td valign="top">Nice shot but the foreground lacks interest. Try cropping most of the foreground and about a third of the right side and you will have much more compelling composition. Great exposure and color.</td>', 'Nice shot but the foreground lacks interest. Try cropping most of the foreground and about a third of the right side and you will have much more compelling composition. Great exposure and color.', '2019-03-03 12:26:24.000000', NULL, 1),
(7616726, 1232940, 59740, '<td valign="top">Nice effort but looks more like a snapshot than a planned composition. The only interesting elements are the snow, walk and bare trees. Try removing everything else that doesn''t add to the photo.</td>', 'Nice effort but looks more like a snapshot than a planned composition. The only interesting elements are the snow, walk and bare trees. Try removing everything else that doesn''t add to the photo.', '2019-03-03 12:28:22.000000', NULL, 1),
(7616728, 1233183, 59740, '<td valign="top">Nice photo but is spoiled by the building being tilted to the right. This could easily be corrected in post processing. Also, the interesting elements are the foreground trees and the building. I would try cropping off some of the photo to the left of the building.</td>', 'Nice photo but is spoiled by the building being tilted to the right. This could easily be corrected in post processing. Also, the interesting elements are the foreground trees and the building. I would try cropping off some of the photo to the left of the building.', '2019-03-03 12:31:24.000000', NULL, 1),
(7616729, 1233203, 59740, '<td valign="top">Nice.</td>', 'Nice.', '2019-03-03 12:32:20.000000', NULL, 1),
(7616731, 1233260, 59740, '<td valign="top">Very nice composition.</td>', 'Very nice composition.', '2019-03-03 12:33:02.000000', NULL, 1),
(7616732, 1233158, 59740, '<td valign="top">Could have been a good photo but nothing is in focus.</td>', 'Could have been a good photo but nothing is in focus.', '2019-03-03 12:34:03.000000', NULL, 1),
(7616734, 1233301, 59740, '<td valign="top">Great photo. Brrrrrr!</td>', 'Great photo. Brrrrrr!', '2019-03-03 12:35:51.000000', NULL, 1),
(7616737, 1233263, 59740, '<td valign="top">Most of this photo is out of focus and the sun flare doesn''t help it.</td>', 'Most of this photo is out of focus and the sun flare doesn''t help it.', '2019-03-03 12:37:23.000000', NULL, 1),
(7616739, 1232928, 59740, '<td valign="top">Charming shot. It probably doesn''t need so much of the plain snow background since the subject is the mill.</td>', 'Charming shot. It probably doesn''t need so much of the plain snow background since the subject is the mill.', '2019-03-03 12:38:40.000000', NULL, 1),
(7616741, 1233014, 59740, '<td valign="top">Nice photo. To me, the most interesting elements are the three trees and large barn on the left. I would try cropping out the two buildings to the right of the largest tree</td>', 'Nice photo. To me, the most interesting elements are the three trees and large barn on the left. I would try cropping out the two buildings to the right of the largest tree', '2019-03-03 12:40:42.000000', NULL, 1),
(7616743, 1232529, 59740, '<td valign="top">This shot has great potential but there is too much of a good thing. I would suggest cropping out most of the foreground below the icicles and most some of the right side so that the light post isn''t so centered.</td>', 'This shot has great potential but there is too much of a good thing. I would suggest cropping out most of the foreground below the icicles and most some of the right side so that the light post isn''t so centered.', '2019-03-03 12:43:46.000000', NULL, 1),
(7616744, 1233071, 59740, '<td valign="top">Nice photo. Great exposure and color.</td>', 'Nice photo. Great exposure and color.', '2019-03-03 12:44:39.000000', NULL, 1),
(7616745, 1232672, 59740, '<td valign="top">You have certainly captured winter but I wish the subject were more interesting.</td>', 'You have certainly captured winter but I wish the subject were more interesting.', '2019-03-03 12:45:46.000000', NULL, 1),
(7616747, 1232985, 59740, '<td valign="top">Wow! Great shot. At first I thought the ice was sharpening artifacts until I realized that the twigs are covered with ice.</td>', 'Wow! Great shot. At first I thought the ice was sharpening artifacts until I realized that the twigs are covered with ice.', '2019-03-03 12:48:11.000000', NULL, 1),
(7616749, 1232722, 59740, '<td valign="top">This would have been a nice shot if it weren''t so blurred.</td>', 'This would have been a nice shot if it weren''t so blurred.', '2019-03-03 12:48:46.000000', NULL, 1),
(7616752, 1233290, 59740, '<td valign="top">Almost a perfect shot if the tree hadn''t been cut off.</td>', 'Almost a perfect shot if the tree hadn''t been cut off.', '2019-03-03 12:49:51.000000', NULL, 1),
(7616753, 1232563, 59740, '<td valign="top">Nice composition but the foreground is too blurred.</td>', 'Nice composition but the foreground is too blurred.', '2019-03-03 12:50:24.000000', NULL, 1),
(7616755, 1233291, 59740, '<td valign="top">Fascinating shot. It looks to me like the castle/fort is tilted slightly to the right and I wouldn''t have centered it in the composition. Nice work.</td>', 'Fascinating shot. It looks to me like the castle/fort is tilted slightly to the right and I wouldn''t have centered it in the composition. Nice work.', '2019-03-03 12:52:10.000000', NULL, 1),
(7616756, 1233033, 59740, '<td valign="top">Nice color but not very sharp. Also, the ship is sailing out of the picture.</td>', 'Nice color but not very sharp. Also, the ship is sailing out of the picture.', '2019-03-03 12:53:36.000000', NULL, 1),
(7616982, 1232985, 46873, '<td valign="top">Great perspective!</td>', 'Great perspective!', '2019-03-04 07:33:34.000000', NULL, 1),
(7617023, 1232917, 103032, '<td valign="top">Best of the bunch.  Blue ribbon.</td>', 'Best of the bunch.  Blue ribbon.', '2019-03-04 13:42:29.000000', NULL, 1),
