(7617374, 1232982, 115814, '<td valign="top">Exceptional tonal control here. Well done!</td>', 'Exceptional tonal control here. Well done!', '2019-03-05 21:08:48.000000', NULL, 1),
(7617379, 1233301, 115814, '<td valign="top">Nicely done! Good use of white balance shift in the warm glow of the headlights.</td>', 'Nicely done! Good use of white balance shift in the warm glow of the headlights.', '2019-03-05 21:14:21.000000', NULL, 1),
(7617380, 1232823, 115814, '<td valign="top">I like the foreground snow setting the scene. Stong composition and processing.</td>', 'I like the foreground snow setting the scene. Stong composition and processing.', '2019-03-05 21:16:26.000000', NULL, 1),
(7617381, 1233260, 115814, '<td valign="top">The color toning is nicely done and effective in setting a mood. Nice!</td>', 'The color toning is nicely done and effective in setting a mood. Nice!', '2019-03-05 21:17:04.000000', NULL, 1),
(7617382, 1232968, 115814, '<td valign="top">This has a wonderful initial impact! Upon closer viewing it seems as if there''s some sensor dust and some unevenness in the transition from the subtle grey around the subject to the pure whites at the edges. Despite that, I scored this high and really like the overall impact.</td>', 'This has a wonderful initial impact! Upon closer viewing it seems as if there''s some sensor dust and some unevenness in the transition from the subtle grey around the subject to the pure whites at the edges. Despite that, I scored this high and really like the overall impact.', '2019-03-05 21:17:10.000000', NULL, 1),
(7617406, 1233070, 50695, '<td valign="top">this is my favorite of the challenge. Nice sense of scale and depth and mystery</td>', 'this is my favorite of the challenge. Nice sense of scale and depth and mystery', '2019-03-05 23:10:36.000000', NULL, 1),
